package com.dedhapp3n.pokeldn.frlg

enum class FrlgSaveRestoreStage { WAITING_CLIENT, VALIDATING, READING_FOOTERS, WRITING, LOADING, CLOSING, COMPLETED, REFUSED, FAILED }
internal data class FrlgRestoreTransferDiagnostic(
    val planIndex:Int,val total:Int,val physicalSector:Int,val sectorId:Int?,val kind:FrlgSaveRestoreEngine.WriteKind,
    val tokenBytes:Int,val messageCount:Int,val blockCount:Int,val startedAtMillis:Long,val responseAtMillis:Long?,val durationMillis:Long?,
    val failureMask:Long?,val reliableOutstanding:Int,val rfuIn:Long,val rfuOut:Long,val status:String,
)
internal data class FrlgSaveRestoreGiftSnapshot(val stage:FrlgSaveRestoreStage,val cartridge:FrlgCartridge,val gameCode:String?,val sectorsWritten:Int,val totalSectors:Int,val failureMask:Long?,val loadResult:Int?,val detail:String?,val disconnectRequested:Boolean,val successful:Boolean,val transferDiagnostics:List<FrlgRestoreTransferDiagnostic>)
internal class FrlgRestoreResponseWatchdog(private val timeoutMillis:Long){private var since:Long?=null;fun begin(now:Long){since=now};fun complete(){since=null};fun expired(now:Long)=since?.let{now-it>=timeoutMillis}==true;val active get()=since!=null}
internal fun restorePeerDepartureCompletes(successful:Boolean,stage:FrlgSaveRestoreStage)=successful&&stage==FrlgSaveRestoreStage.CLOSING

/** RFU/Mystery Gift adapter for the isolated upstream-compatible restore core. */
internal class FrlgSaveRestoreGiftEngine(private val linkCartridge:FrlgCartridge,save:ByteArray,startupStandbyCount:Int=0,echoStartupStandby:Boolean=true,
    private val responseTimeoutMillis:Long=RESTORE_RESPONSE_TIMEOUT_MS,private val clockMillis:()->Long=System::currentTimeMillis){
    private val core=FrlgSaveRestoreEngine(save,linkCartridge.game,linkCartridge.language);private var stage=FrlgSaveRestoreStage.WAITING_CLIENT;private var detail:String?="Waiting for Mystery Gift client";private var idle=0
    private val words=ArrayDeque<IntArray>();private val blocks=ArrayDeque<Pair<ByteArray,Int>>();private var sender:RfuBlockSender?=null;private var gap=0;private val receiver=RfuBlockReceiver();private val messageReceiver=MgMessageReceiver();private var expecting:Int?=null;private var afterSend:(()->Unit)?=null
    private var closeRetry=0;private var closeGrace:Int?=null;private var exitCount=startupStandbyCount+1;var disconnectRequested=false;private set
    private val diagnostics=mutableListOf<FrlgRestoreTransferDiagnostic>();private val watchdog=FrlgRestoreResponseWatchdog(responseTimeoutMillis);private var awaitingSince:Long?=null;private var trackedWrite:FrlgSaveRestoreEngine.WritePlanInfo?=null
    private var reliableOutstanding=0;private var rfuIn=0L;private var rfuOut=0L
    init{if(echoStartupStandby)repeat(4){words+=intArrayOf(FrlgRfu.READY_EXIT_STANDBY,startupStandbyCount,0,0,0,0,0)}}
    fun receive(slot:ByteArray){if(slot.all{it==0.toByte()}){if(stage==FrlgSaveRestoreStage.WAITING_CLIENT&&++idle>=20)pumpCore();return};idle=0;val op=u16Restore(slot)and FrlgRfu.MASK;if(op==FrlgRfu.READY_CLOSE_LINK){val count=if(slot.size>=4)u16Restore(slot,2)else 0;exitCount=maxOf(exitCount,count);repeat(4){words+=intArrayOf(FrlgRfu.READY_CLOSE_LINK,count,0,0,0,0,0)};if(stage==FrlgSaveRestoreStage.CLOSING&&closeGrace==null)closeGrace=300;return};receiver.receive(slot)?.let(::onBlock)}
    fun checkLiveness()=checkTimeout()
    fun tick():IntArray{checkTimeout();if(stage==FrlgSaveRestoreStage.CLOSING&&!disconnectRequested){closeGrace?.let{if(it<=1)disconnectRequested=true else closeGrace=it-1};if(closeGrace==null&&--closeRetry<=0){queueClose();closeRetry=60}};if(words.isNotEmpty())return words.removeFirst();if(gap>0){gap--;return IntArray(7)};if(sender==null&&blocks.isNotEmpty()){val(b,r)=blocks.removeFirst();sender=RfuBlockSender(b,r)};sender?.let{val out=it.tick();if(it.done){sender=null;gap=36;if(blocks.isEmpty()){val next=afterSend;afterSend=null;next?.invoke()}};return out};return IntArray(7)}
    fun snapshot():FrlgSaveRestoreGiftSnapshot{val s=core.snapshot();return FrlgSaveRestoreGiftSnapshot(stage,FrlgCartridge(s.game?:linkCartridge.game,s.language?:linkCartridge.language,linkCartridge.version,linkCartridge.languageId),s.gameCode,s.sectorsWritten,s.totalSectors,s.failureMask,s.loadResult,detail,disconnectRequested,core.successful,diagnostics.toList())}
    fun updateTransportCounters(outstanding:Int,input:Long,output:Long){reliableOutstanding=outstanding;rfuIn=input;rfuOut=output}
    fun onPeerLeft(){if(stage==FrlgSaveRestoreStage.COMPLETED||stage==FrlgSaveRestoreStage.FAILED||stage==FrlgSaveRestoreStage.REFUSED)return;if(restorePeerDepartureCompletes(core.successful,stage)){stage=FrlgSaveRestoreStage.COMPLETED;detail="Save restored successfully"}else{val s=core.snapshot();val where=s.currentWrite?.let{" while restoring sector ${it.index} of ${it.total}"}?:"";core.failConnection("Connection lost$where");stage=FrlgSaveRestoreStage.FAILED;detail="Connection lost$where";finishTracked("peer-left",null)}}
    fun markDisconnected()=onPeerLeft()
    private fun onBlock(block:ByteArray){val wanted=expecting?:return;val msg=try{messageReceiver.receive(block,wanted)}catch(e:IllegalArgumentException){fail(e.message?:"Invalid Mystery Gift message");return}?:return;expecting=null;awaitingSince=null;watchdog.complete();val mask=if(msg.size>=4&&(stage==FrlgSaveRestoreStage.WRITING||stage==FrlgSaveRestoreStage.LOADING))u32Restore(msg)else null;finishTracked("response",mask);core.onReceived(wanted,msg);pumpCore()}
    private fun pumpCore(){val s=core.snapshot();stage=when(s.stage){FrlgSaveRestoreEngine.Stage.REQUESTING_GAME_DATA->FrlgSaveRestoreStage.VALIDATING;FrlgSaveRestoreEngine.Stage.VALIDATING->FrlgSaveRestoreStage.VALIDATING;FrlgSaveRestoreEngine.Stage.READING_FOOTERS->FrlgSaveRestoreStage.READING_FOOTERS;FrlgSaveRestoreEngine.Stage.WRITING->FrlgSaveRestoreStage.WRITING;FrlgSaveRestoreEngine.Stage.LOADING->FrlgSaveRestoreStage.LOADING;FrlgSaveRestoreEngine.Stage.ENDING->FrlgSaveRestoreStage.LOADING;FrlgSaveRestoreEngine.Stage.COMPLETED->FrlgSaveRestoreStage.COMPLETED;FrlgSaveRestoreEngine.Stage.REFUSED->FrlgSaveRestoreStage.REFUSED;FrlgSaveRestoreEngine.Stage.FAILED->FrlgSaveRestoreStage.FAILED};detail=s.detail;s.currentWrite?.let(::trackWriteStart)
        when(val a=core.action){is FrlgSaveRestoreEngine.Action.Send->sendMessage(a.ident,a.payload,if(a.ident==FrlgSaveRestoreEngine.RAM_SCRIPT)3 else 2){core.onSent();pumpCore()};is FrlgSaveRestoreEngine.Action.Receive->expect(a.ident);FrlgSaveRestoreEngine.Action.Done->beginClose()}}
    private fun beginClose(){stage=FrlgSaveRestoreStage.CLOSING;detail=if(core.successful)"Save restored; closing link" else core.snapshot().detail;queueClose();closeRetry=60}
    private fun queueClose(){repeat(4){words+=intArrayOf(FrlgRfu.READY_CLOSE_LINK,exitCount,0,0,0,0,0)}}
    private fun expect(id:Int){expecting=id;messageReceiver.reset();if(stage==FrlgSaveRestoreStage.WRITING||stage==FrlgSaveRestoreStage.LOADING){awaitingSince=clockMillis();watchdog.begin(awaitingSince!!);trackedWrite?.let{plan->val index=diagnostics.indexOfLast{it.planIndex==plan.index&&it.responseAtMillis==null};if(index>=0)diagnostics[index]=diagnostics[index].copy(status="waiting",reliableOutstanding=reliableOutstanding,rfuIn=rfuIn,rfuOut=rfuOut)}}}
    private fun sendMessage(id:Int,payload:ByteArray,repeats:Int,done:()->Unit){MgMessage.build(id,payload).forEach{blocks+=it to repeats};afterSend=done}
    private fun fail(text:String){core.failConnection(text);stage=FrlgSaveRestoreStage.FAILED;detail=text;awaitingSince=null;watchdog.complete();finishTracked("failed",null);abortTransfer()}
    private fun checkTimeout(){if(!watchdog.expired(clockMillis()))return;val plan=trackedWrite;val text=if(plan!=null)"Restore connection timed out while waiting for sector ${plan.index} of ${plan.total} readback" else "Restore connection timed out while loading the restored save";core.failConnection(text);stage=FrlgSaveRestoreStage.FAILED;detail=text;expecting=null;awaitingSince=null;watchdog.complete();finishTracked("timeout",null);abortTransfer()}
    private fun finishTracked(status:String,mask:Long?){val plan=trackedWrite?:return;val at=clockMillis();val index=diagnostics.indexOfLast{it.planIndex==plan.index&&it.responseAtMillis==null};if(index>=0){val old=diagnostics[index];diagnostics[index]=old.copy(responseAtMillis=at,durationMillis=at-old.startedAtMillis,failureMask=mask,reliableOutstanding=reliableOutstanding,rfuIn=rfuIn,rfuOut=rfuOut,status=status)};trackedWrite=null}
    private fun trackWriteStart(plan:FrlgSaveRestoreEngine.WritePlanInfo){if(trackedWrite?.index==plan.index)return;trackedWrite=plan;diagnostics+=FrlgRestoreTransferDiagnostic(plan.index,plan.total,plan.physicalSector,plan.sectorId,plan.kind,plan.tokenBytes,plan.messageCount,plan.blockCount,clockMillis(),null,null,null,reliableOutstanding,rfuIn,rfuOut,"sending")}
    private fun abortTransfer(){words.clear();blocks.clear();sender=null;afterSend=null;gap=0;disconnectRequested=true}
    companion object{const val RESTORE_RESPONSE_TIMEOUT_MS=120_000L}
}
private fun u16Restore(d:ByteArray,a:Int=0)=(d[a].toInt()and 255)or((d[a+1].toInt()and 255)shl 8)
private fun u32Restore(d:ByteArray,a:Int=0)=(0..3).fold(0L){v,i->v or((d[a+i].toInt()and 255).toLong()shl(8*i))}
